ock": 5}, {"id": "gold-44", "label": "Gold, EU 44", "color": "gold", "size": "44", "price": 4447, "regularPrice": 4447, "stock": 5}, {"id": "gold-45", "label": "Gold, EU 45", "color": "gold", "size": "45", "price": 4447, "regularPrice": 4447, "stock": 5}], "images": [{"src": "/products/white-red-hero.jpg", "thumb": "/products/white-red-hero.jpg"}, {"src": "/products/white-red-onfeet.jpg", "thumb": "/products/white-red-onfeet.jpg"}, {"src": "/products/beige-orange-hero.jpg", "thumb": "/products/beige-orange-hero.jpg"}, {"src": "/products/beige-orange-onfeet.jpg", "thumb": "/products/beige-orange-onfeet.jpg"}, {"src": "/products/pink-hero.jpg", "thumb": "/products/pink-hero.jpg"}, {"src": "/products/pink-onfeet.jpg", "thumb": "/products/pink-onfeet.jpg"}, {"src": "/products/gold-hero.jpg", "thumb": "/products/gold-hero.jpg"}, {"src": "/products/gold-onfeet-1.jpg", "thumb": "/products/gold-onfeet-1.jpg"}, {"src": "/products/gold-onfeet-2.jpg", "thumb": "/products/gold-onfeet-2.jpg"}, {"src": "/products/detail-ankle.jpg", "thumb": "/products/detail-ankle.jpg"}, {"src": "/products/detail-spine.jpg", "thumb": "/products/detail-spine.jpg"}, {"src": "/products/detail-studs.jpg", "thumb": "/products/detail-studs.jpg"}, {"src": "/products/colour-options.jpg", "thumb": "/products/colour-options.jpg"}, {"src": "/products/pink-gold-pair.jpg", "thumb": "/products/pink-gold-pair.jpg"}], "colors": [{"key": "white-red", "name": "White / Red", "hex": "#F4F4F1", "images": [0, 1]}, {"key": "beige-orange", "name": "Beige / Orange", "hex": "#E6D3B6", "images": [2, 3]}, {"key": "pink", "name": "Pink", "hex": "#F08DB7", "images": [4, 5]}, {"key": "gold", "name": "Gold", "hex": "#CDB57D", "images": [6, 7, 8]}], "details": [9, 10, 11, 12, 13], "badge": "New", "description": "Long TPU stud football boots with a breathable mesh upper and a flexible wraparound ankle collar, made for training and match days on natural grass.\n\nThe TPU support spine limits twisting, and the long studs grip for quick stops, sharp turns and sprints. Available in White / Red, Beige / Orange, Pink and Gold, in sizes 35 to 45.", "ingredients": ["Product: Football training boots", "Upper: Mesh", "Sole: Long studs / TPU", "Sizes: 35 to 45", "Colours: White / Red, Beige / Orange, Pink, Gold"], "benefits": ["Wraparound ankle collar with a snug, flexible fit", "Long TPU studs for grip on natural grass", "TPU support spine to limit twisting", "Breathable mesh upper"], "howToUse": ["Pick the EU size that matches your foot length. If you are between sizes, go one size up.", "Wipe off mud after every session and let the boots air dry away from direct heat.", "Keep them in a breathable bag, not a closed plastic one."], "published": true, "sort": 1}'::jsonb, true, 1)
