insert into public.products (id, slug, data, published, sort)
values ('striker-boots', 'striker-football-boots', '{"id": "striker-boots", "slug": "striker-football-boots", "name": "Striker Football Boots", "title": "Striker Football Boots – Spike (FG) and Flat (TF) Soles, 4 Colours", "brand": "247BD", "gender": "unisex", "category": "boots", "price": 1997, "regularPrice": 1997, "stock": 0, "colors": [{"key": "white-fg", "name": "White / Pink", "hex": "#F4F4F6", "images": [0], "sole": "Spike (FG)"}, {"key": "white-tf", "name": "White / Blue", "hex": "#DCE9F7", "images": [1], "sole": "Flat (TF)"}, {"key": "black-fg", "name": "Black / Green", "hex": "#111111", "images": [2], "sole": "Spike (FG)"}, {"key": "black-tf", "name": "Black / Green", "hex": "#1D2A1D", "images": [3], "sole": "Flat (TF)"}, {"key": "mint-fg", "name": "Mint / Orange", "hex": "#A9E4D2", "images": [4, 5], "sole": "Spike (FG)"}, {"key": "mint-tf", "name": "Mint / Orange", "hex": "#8CD6C0", "images": [6], "sole": "Flat (TF)"}, {"key": "pink-fg", "name": "Pink / Black", "hex": "#F29AB0", "images": [7], "sole": "Spike (FG)"}, {"key": "pink-tf", "name": "Pink / Black", "hex": "#F6B3C4", "images": [8], "sole": "Flat (TF)"}], "details": [9], "badge": "New", "description": "Lightweight football boots with a textured synthetic upper and a snug lace-up fit. Choose the spike sole (long studs, FG) for natural grass or the flat sole (turf, TF) for artificial turf, concrete and hard grounds.\n\nAvailable in White / Pink, Black / Green, Mint / Orange and Pink / Black, in sizes 35 to 45. See the sole and size guide in the gallery.", "ingredients": ["Product: Football boots", "Upper: Textured synthetic", "Sole options: Spike (long studs, FG) or Flat (turf, TF)", "Sizes: 35 to 45", "Colours: White / Pink, Black / Green, Mint / Orange, Pink / Black"], "benefits": ["Lightweight textured upper", "Long studs (FG) for grip on grass", "Soft turf sole (TF) for artificial turf and hard grounds", "Good choice for beginners (TF) and regular players (FG)"], "howToUse": ["Turf (TF) is the safe choice for children, teens and beginners and for artificial turf, plastic and cement floors.", "Long stud (FG) is for players with some experience. Check that the ground suits long studs before you buy.", "Pick the EU size from your foot length using the size guide. If you are between sizes, go one size up.", "Wipe off mud after every session and let the boots air dry away from direct heat."], "published": true, "sort": 4, "images": [{"src": "/products/striker-white-fg.jpg", "thumb": "/products/striker-white-fg.jpg"}, {"src": "/products/striker-white-tf.jpg", "thumb": "/products/striker-white-tf.jpg"}, {"src": "/products/striker-black-fg.jpg", "thumb": "/products/striker-black-fg.jpg"}, {"src": "/products/striker-black-tf.jpg", "thumb": "/products/striker-black-tf.jpg"}, {"src": "/products/striker-mint-fg.jpg", "thumb": "/products/striker-mint-fg.jpg"}, {"src": "/products/striker-mint-hero.jpg", "thumb": "/products/striker-mint-hero.jpg"}, {"src": "/products/striker-mint-tf.jpg", "thumb": "/products/striker-mint-tf.jpg"}, {"src": "/products/striker-pink-fg.jpg", "thumb": "/products/striker-pink-fg.jpg"}, {"src": "/products/striker-pink-tf.jpg", "thumb": "/products/striker-pink-tf.jpg"}, {"src": "/products/striker-size-guide.jpg", "thumb": "/products/striker-size-guide.jpg"}], "variations": [{"id": "white-fg-35", "label": "White / Pink, Spike (FG), EU 35", "color": "white-fg", "size": "35", "price": 1997, "regularPrice": null, "stock": 5}, {"id": "white-fg-36", "label": "White / Pink, Spike (FG), EU 36", "color": "white-fg", "size": "36", "price": 1997, "regularPrice": null, "stock": 5}, {"id": "white-fg-37", "label": "White / Pink, Spike (FG), EU 37", "color": "white-fg", "size": "37", "price": 1997, "regularPrice": null, "stock": 5}, {"id": "white-fg-38", "label": "White / Pink, Spike (FG), EU 38", "color": "white-fg", "size": "38", "price": 1997, "regularPrice": null, "stock": 5}, {"id": "white-fg-39", "label": "White / Pink, Spike (FG), EU 39", "color": "whit