insert into public.products (id, slug, data, published, sort)
values ('grip-socks', 'grip-football-socks-2-pair-pack', '{"id": "grip-socks", "slug": "grip-football-socks-2-pair-pack", "name": "Grip Football Socks (2 Pair Pack)", "title": "Grip Football Socks – 2 Pair Pack, Anti-Slip, Long Over-Calf", "brand": "247BD", "gender": "unisex", "category": "accessories", "price": 450, "regularPrice": 450, "stock": 0, "colors": [{"key": "black-white", "name": "Black + White", "hex": "linear-gradient(135deg, #111111 50%, #F4F4F6 50%)", "images": [1, 2]}, {"key": "black-red", "name": "Black + Red", "hex": "linear-gradient(135deg, #111111 50%, #E0261F 50%)", "images": [1, 3]}, {"key": "black-blue", "name": "Black + Blue", "hex": "linear-gradient(135deg, #111111 50%, #1F4FE0 50%)", "images": [1, 0]}, {"key": "white-red", "name": "White + Red", "hex": "linear-gradient(135deg, #F4F4F6 50%, #E0261F 50%)", "images": [2, 3]}, {"key": "white-blue", "name": "White + Blue", "hex": "linear-gradient(135deg, #F4F4F6 50%, #1F4FE0 50%)", "images": [2, 0]}, {"key": "red-blue", "name": "Red + Blue", "hex": "linear-gradient(135deg, #E0261F 50%, #1F4FE0 50%)", "images": [3, 0]}], "details": [4], "badge": "New", "description": "Long football grip socks with rubber grip dots on the leg and a cushioned, grippy sole, so your foot stays put inside the boot and your shin guard stays in place.\n\nEach pack has 2 pairs. Pick any 2 colours from Black, White, Red and Blue. One free size fits most adults.", "ingredients": ["Product: Long football grip socks", "Pack: 2 pairs, you choose the 2 colours", "Colours: Black, White, Red, Blue", "Grip: Rubber grip dots on the heel, leg and sole", "Sole: Cushioned", "Size: Free size, stretch fit"], "benefits": ["Grip dots stop your foot sliding inside the boot", "Grip on the leg helps hold shin guards in place", "Cushioned sole for comfort on long sessions", "Long over-calf length, stretch fit"], "howToUse": ["Choose your 2 colours, then add the pack to the cart. You get one pair of each colour.", "Wash inside out in cool water and air dry so the grip dots last longer.", "Do not iron the grip dots."], "published": true, "sort": 5, "images": [{"src": "/products/grip-socks-blue.jpg", "thumb": "/products/grip-socks-blue.jpg"}, {"src": "/products/grip-socks-black.jpg", "thumb": "/products/grip-socks-black.jpg"}, {"src": "/products/grip-socks-white.jpg", "thumb": "/products/grip-socks-white.jpg"}, {"src": "/products/grip-socks-red.jpg", "thumb": "/products/grip-socks-red.jpg"}, {"src": "/products/grip-socks-colours.jpg", "thumb": "/products/grip-socks-colours.jpg"}], "variations": [{"id": "black-white-free", "label": "Black + White (2 pairs), Free size", "color": "black-white", "size": "Free", "price": 450, "regularPrice": null, "stock": 10}, {"id": "black-red-free", "label": "Black + Red (2 pairs), Free size", "color": "black-red", "size": "Free", "price": 450, "regularPrice": null, "stock": 10}, {"id": "black-blue-free", "label": "Black + Blue (2 pairs), Free size", "color": "black-blue", "size": "Free", "price": 450, "regularPrice": null, "stock": 10}, {"id": "white-red-free", "label": "White + Red (2 pairs), Free size", "color": "white-red", "size": "Free", "price": 450, "regularPrice": null, "stock": 10}, {"id": "white-blue-free", "label": "White + Blue (2 pairs), Free size", "color": "white-blue", "size": "Free", "price": 450, "regularPrice": null, "stock": 10}, {"id": "red-blue-free", "label": "Red + Blue (2 pairs), Free size", "color": "red-blue", "size": "Free", "price": 450, "regularPrice": null, "stock": 10}]}'::jsonb, true, 5)
on conflict (slug) do update set data = excluded.data, published = excluded.published, sort = excluded.sort;

insert into public.products (id, slug, data, published, sort)
values ('ankle-support', 'ankle-support-compression-brace', '{"id": "ankle-support", "slug": "ankle-support-compression-brace", "name": "Ankle Support Compression Brace", "title": "Ankle Support Compression Brace – Slim 1mm, Adjustable Strap, 3 Colours", "brand": "247BD", "gender": "unisex", "category": "accessories", "price": 199, "regularPrice": 199, "stock": 0, "sizeLabel": "Pack", "colors": [{"key": "green", "name": "Green", "hex": "#B7F000", "images": [1]}, {"key": "purple", "name": "Purple", "hex": "#B9A2E8", "images": [0]}, {"key": "grey", "name": "Grey / White", "hex": "#D4D4D8", "images": [0]}], "details": [1, 2, 3, 4, 5], "badge": "New", "description": "Slim compression ankle support for football, running and gym. The high-stretch, skin-friendly fabric is as thin as 1mm, so it fits inside your boot or shoe without feeling bulky.\n\nA Y-shaped strap with a strong velcro closure gives two-way compression around the ankle, and the open heel keeps it comfortable. Buy 1 piece for 199 tk or a pair for 357 tk. Available in Green, Purple and Grey / White.", "ingredients": ["Product: Compression ankle support", "Thickness: As thin as 1mm", "Fabric: High-stretch, breathable, sweat-wicking", "Design: Y-shaped strap, open heel, textured grip pattern", "Closure: Strong velcro strap", "Colours: Green, Purple, Grey / White", "Pack: 1 piece or 2 pieces (pair)"], "benefits": ["Two-way compression support for the ankle", "Slim 1mm fabric, fits inside boots and shoes", "Breathable, sweat-wicking and skin-friendly", "Open heel and adjustable velcro strap"], "howToUse": ["Slide it over the foot and position it around the ankle with the heel open.", "Wrap the strap around the ankle in a Y shape and press the velcro closed. Adjust the tightness so it is firm but comfortable.", "Wash by hand in cool water and air dry. Keep the velcro clean."], "published": true, "sort": 6, "images": [{"src": "/products/ankle-colours.jpg", "thumb": "/products/ankle-colours.jpg"}, {"src": "/products/ankle-hero.jpg", "thumb": "/products/ankle-hero.jpg"}, {"src": "/products/ankle-callouts.jpg", "thumb": "/products/ankle-callouts.jpg"}, {"src": "/products/ankle-y-support.jpg", "thumb": "/products/ankle-y-support.jpg"}, {"src": "/products/ankle-specs.jpg", "thumb": "/products/ankle-specs.jpg"}, {"src": "/products/ankle-invisible.jpg", "thumb": "/products/ankle-invisible.jpg"}], "variations": [{"id": "green-1", "label": "Green, 1 piece", "color": "green", "size": "Single", "price": 199, "regularPrice": null, "stock": 10}, {"id": "green-2", "label": "Green, 2 pieces (pair)", "color": "green", "size": "Pair", "price": 357, "regularPrice": null, "stock": 10}, {"id": "purple-1", "label": "Purple, 1 piece", "color": "purple", "size": "Single", "price": 199, "regularPrice": null, "stock": 10}, {"id": "purple-2", "label": "Purple, 2 pieces (pair)", "color": "purple", "size": "Pair", "price": 357, "regularPrice": null, "stock": 10}, {"id": "grey-1", "label": "Grey / White, 1 piece", "color": "grey", "size": "Single", "price": 199, "regularPrice": null, "stock": 10}, {"id": "grey-2", "label": "Grey / White, 2 pieces (pair)", "color": "grey", "size": "Pair", "price": 357, "regularPrice": null, "stock": 10}]}'::jsonb, true, 6)
on conflict (slug) do update set data = excluded.data, published = excluded.published, sort = excluded.sort;

insert into public.products (id, slug, data, published, sort)
values ('shinguard-set', 'shin-guard-sleeve-set', '{"id": "shinguard-set", "slug": "shin-guard-sleeve-set", "name": "Shin Guard and Sleeve Set", "title": "Shin Guard and Sleeve Set – Shin Pads with Pocket Sleeves, 3 Colours", "brand": "247BD", "gender": "unisex", "category": "accessories", "price": 493, "regularPrice": 493, "stock": 0, "colors": [{"key": "white", "name": "White", "hex": "#F4F4F6", "images": [0, 3, 4, 5, 6]}, {"key": "black", "name": "Black", "hex": "#111111", "images": [1]}, {"key": "blue", "name": "Blue", "hex": "#1F6FE0", "images": [2]}], "details": [3, 4, 5, 6], "badge": "New", "description": "2-piece football set: 1 pair of shin guards and 1 pair of mesh sleeves with a built-in pocket.\n\nSlide the shin guard into the sleeve pocket and pull the sleeve on. The guard stays in place on the shin without tape, and the breathable mesh keeps your leg cool. Available in White, Black and Blue.", "ingredients": ["Set: 1 pair of shin guards + 1 pair of sleeves", "Shin guards: Hard shell, lightweight", "Sleeves: Breathable mesh with a pocket for the guard", "Colours: White, Black, Blue", "Size: Free size, stretch fit"], "benefits": ["Guard stays in place, no tape needed", "Breathable mesh sleeve", "Pocket holds the shin guard securely", "Light hard-shell protection for matches and training"], "howToUse": ["Put the shin guard into the pocket of the sleeve.", "Pull the sleeve onto your leg with the guard over the shin, then put your football socks on top if you like.", "Wash the sleeves by hand and air dry. Wipe the guards clean with a damp cloth."], "published": true, "sort": 7, "images": [{"src": "/products/shinguard-set-white.jpg", "thumb": "/products/shinguard-set-white.jpg"}, {"src": "/products/shinguard-set-black.jpg", "thumb": "/products/shinguard-set-black.jpg"}, {"src": "/products/shinguard-set-blue.jpg", "thumb": "/products/shinguard-set-blue.jpg"}, {"src": "/products/shinguard-white-1.jpg", "thumb": "/products/shinguard-white-1.jpg"}, {"src": "/products/shinguard-white-2.jpg", "thumb": "/products/shinguard-white-2.jpg"}, {"src": "/products/shinguard-white-3.jpg", "thumb": "/products/shinguard-white-3.jpg"}, {"src": "/products/shinguard-white-4.jpg", "thumb": "/products/shinguard-white-4.jpg"}], "variations": [{"id": "white-free", "label": "White, Free size", "color": "white", "size": "Free", "price": 493, "regularPrice": null, "stock": 10}, {"id": "black-free", "label": "Black, Free size", "color": "black", "size": "Free", "price": 493, "regularPrice": null, "stock": 10}, {"id": "blue-free", "label": "Blue, Free size", "color": "blue", "size": "Free", "price": 493, "regularPrice": null, "stock": 10}]}'::jsonb, true, 7)
on conflict (slug) do update set data = excluded.data, published = excluded.published, sort = excluded.sort;

insert into public.products (id, slug, data, published, sort)
values ('laceless-boots', 'laceless-football-boots', '{"id": "laceless-boots", "slug": "laceless-football-boots", "name": "Laceless Football Boots", "title": "Laceless Football Boots – Slip-On Low-Top, Spike (FG) and Flat (TF) Soles, 3 Colours", "brand": "247BD", "gender": "unisex", "category": "boots", "price": 2278, "regularPrice": 2278, "stock": 0, "colors": [{"key": "white-fg", "name": "White / Blue", "hex": "#EAF2FA", "sole": "Spike (FG)", "images": [0, 1]}, {"key": "purple-fg", "name": "Purple / Green", "hex": "#6A3FA0", "sole": "Spike (FG)", "images": [2, 3, 4]}, {"key": "pink-fg", "name": "Pink", "hex": "#F4B6C0", "sole": "Spike (FG)", "images": [5]}, {"key": "white-tf", "name": "White / Blue", "hex": "#EAF2FA", "sole": "Flat (TF)", "images": [8, 9, 10]}, {"key": "purple-tf", "name": "Purple / Green", "hex": "#6A3FA0", "sole": "Flat (TF)", "images": [6, 7]}], "details": [10, 11], "badge": "New", "description": "Laceless low-top football boots with a one-piece knit-style upper that wraps the foot like a sock, for a clean touch on the ball and no laces to come undone.\n\nThe PU upper is shock-absorbing and low-cut. Choose the spike sole (FG) for natural grass or the flat sole (TF) for artificial turf and hard grounds. Available in White / Blue, Purple / Green and Pink (Pink: spike sole only), in sizes 35 to 45. See the size guide in the gallery.", "ingredients": ["Product: Laceless football boots", "Upper: PU, low-top", "Function: Shock absorption", "Sole options: Spike (long studs, FG) or Flat (turf, TF)", "Sizes: 35 to 45", "Colours: White / Blue, Purple / Green, Pink (spike only)"], "benefits": ["Laceless slip-on fit, nothing to come undone", "Clean surface for ball contact", "Shock-absorbing low-top design", "Spike (FG) for grass, Flat (TF) for turf and hard ground"], "howToUse": ["Choose the sole: Flat (TF) for artificial turf, concrete and mixed grounds, Spike (FG) for natural grass.", "Pick your EU size from your foot length using the size guide. If you are between sizes, go one size up.", "Wipe off mud after every session and let the boots air dry away from direct heat."], "published": true, "sort": 8, "images": [{"src": "/products/laceless-white-fg-1.jpg", "thumb": "/products/laceless-white-fg-1.jpg"}, {"src": "/products/laceless-white-fg-2.jpg", "thumb": "/products/laceless-white-fg-2.jpg"}, {"src": "/products/laceless-purple-fg-1.jpg", "thumb": "/products/laceless-purple-fg-1.jpg"}, {"src": "/products/laceless-purple-fg-2.jpg", "thumb": "/products/laceless-purple-fg-2.jpg"}, {"src": "/products/laceless-purple-fg-3.jpg", "thumb": "/products/laceless-purple-fg-3.jpg"}, {"src": "/products/laceless-pink-fg-1.jpg", "thumb": "/products/laceless-pink-fg-1.jpg"}, {"src": "/products/laceless-purple-tf-1.jpg", "thumb": "/products/laceless-purple-tf-1.jpg"}, {"src": "/products/laceless-purple-tf-2.jpg", "thumb": "/products/laceless-purple-tf-2.jpg"}, {"src": "/products/laceless-white-tf-1.jpg", "thumb": "/products/laceless-white-tf-1.jpg"}, {"src": "/products/laceless-white-tf-2.jpg", "thumb": "/products/laceless-white-tf-2.jpg"}, {"src": "/products/laceless-info.jpg", "thumb": "/products/laceless-info.jpg"}, {"src": "/products/laceless-guide.jpg", "thumb": "/products/laceless-guide.jpg"}], "variations": [{"id": "white-fg-35", "label": "White / Blue, Spike (FG), EU 35", "color": "white-fg", "size": "35", "price": 2278, "regularPrice": null, "stock": 5}, {"id": "white-fg-36", "label": "White / Blue, Spike (FG), EU 36", "color": "white-fg", "size": "36", "price": 2278, "regularPrice": null, "stock": 5}, {"id": "white-fg-37", "label": "White / Blue, Spike (FG), EU 37", "color": "white-fg", "size": "37", "price": 2278, "regularPrice": null, "stock": 5}, {"id": "white-fg-38", "label": "White / Blue, Spike (FG), EU 38", "color": "white-fg", "size": "38", "price": 2278, "regularPrice": null, "stock": 5}, {"id": "white-fg-39", "label": "White / Blue, Spike (FG), EU 39", "color": "white-fg", "size": "39", "price": 2278, "regularP