insert into public.products (id, slug, data, published, sort)
values ('speed-boots', 'speed-football-boots', '{"id": "speed-boots", "slug": "speed-football-boots", "name": "Speed Football Boots", "title": "Speed Football Boots – Knit Upper, Spike Sole (FG), 3 Colours", "brand": "247BD", "gender": "unisex", "category": "boots", "price": 2896, "regularPrice": 2896, "stock": 0, "colors": [{"key": "teal", "name": "Teal / Purple", "hex": "#3CCFB0", "images": [0, 1, 2]}, {"key": "white", "name": "White / Purple / Pink", "hex": "#EEE6F5", "images": [3, 4]}, {"key": "pink", "name": "Pink / Coral", "hex": "#F5B5B5", "images": [5, 6, 7, 8]}], "details": [7, 8, 9], "badge": "New", "description": "Lightweight speed boots with a wrap-around knit upper and a soft TPU layer, spike (FG) sole for grip on the pitch.\n\nThe textured surface adds friction for a more intuitive touch and ball control. Woven laces give a snug wrap and a controlled midfoot lock, and the thicker heel keeps the foot stable. Available in Teal / Purple, White / Purple / Pink and Pink / Coral, in sizes 35 to 45. See the size guide in the gallery.", "ingredients": ["Product: Football boots", "Upper: Wrap-around knit with soft TPU", "Sole: Spike (long studs, FG), suits all kinds of pitches", "Laces: Woven", "Sizes: 35 to 45", "Colours: Teal / Purple, White / Purple / Pink, Pink / Coral"], "benefits": ["Snug wrap-around knit fit", "Textured surface for more friction and ball control", "Thicker heel for a stable fit", "Spike sole (FG) for grip"], "howToUse": ["Pick your EU size from your foot length using the size guide. If you are between sizes, go one size up.", "Spike (FG) boots are made for grass. Check that the ground suits long studs before you play.", "Wipe off mud after every session and let the boots air dry away from direct heat."], "published": true, "sort": 9, "images": [{"src": "/products/speed-teal-1.jpg", "thumb": "/products/speed-teal-1.jpg"}, {"src": "/products/speed-teal-3.jpg", "thumb": "/products/speed-teal-3.jpg"}, {"src": "/products/speed-ground.jpg", "t