values ('laceless-longstud-boots', 'laceless-long-stud-football-boots', '{"id": "laceless-longstud-boots", "slug": "laceless-long-stud-football-boots", "name": "Laceless Long-Stud Football Boots", "title": "Laceless Long-Stud Football Boots – Knit + TPU Upper, TPU Studs, Youth to Adult 32-45", "brand": "247BD", "gender": "unisex", "category": "boots", "price": 2560, "regularPrice": 3490, "stock": 0, "colors": [{"key": "cream", "name": "Cream", "hex": "#EFE6D2", "images": [4, 5]}, {"key": "black", "name": "Black", "hex": "#1A1A1A", "images": [0, 1, 2, 3]}, {"key": "red", "name": "Red", "hex": "#E0392B", "images": [6, 7]}, {"key": "pink", "name": "Pink", "hex": "#F2B5C4", "images": [8, 9]}], "details": [10, 11, 12, 13, 14, 15, 16], "badge": "Offer", "description": "Laceless long-stud football boots with a knit upper joined to TPU panels. The knit zones are light and breathable, while the TPU adds support at the key load points to keep the foot stable when you sprint and change direction.\n\nThe 2.0 TPU long-stud sole is tough and wear-resistant, with forefoot studs for starts and turns and heel studs for steady braking on natural grass or artificial turf. Light enough for training and everyday outdoor wear too.\n\nAvailable in Cream, Black, Red and Pink, in sizes 32 to 45. Regular price ৳3,490, offer price ৳2,560. See the size guide in the gallery. Long studs suit players with some experience: check with your coach that your ground is suitable.", "ingredients": ["Product: Laceless long-stud football boots", "Upper: Knit + TPU", "Sole: 2.0 TPU long studs", "Features: Anti-twist, elastic and breathable", "Sizes: 32 to 45 (standard sizing)", "Colours: Cream, Black, Red, Pink"], "benefits": ["Laceless knit upper with TPU support panels", "Tough, wear-resistant 2.0 TPU long-stud sole", "Forefoot studs for starts and turns, heel studs for steady braking", "For football training, matches and everyday outdoor wear"], "howToUse": ["Choose your EU size (32-45) from your foot length using the size guide. Sizes are standard: order the size you normally wear, and go one size up if you are between sizes.", "Long studs (FG) are for natural grass and suitable grounds. Check with your coach that your ground suits long studs before you order.", "Wipe off mud after every session and let the boots air dry away from direct heat."], "published": true, "sort": 13, "images": [{"src": "/products/lb-black-1.jpg", "thumb": "/products/lb-black-1.jpg"}, {"src": "/products/lb-black-2.jpg", "thumb": "/products/lb-black-2.jpg"}, {"src": "/products/lb-black-3.jpg", "thumb": "/products/lb-black-3.jpg"}, {"src": "/products/lb-black-4.jpg", "thumb": "/products/lb-black-4.jpg"}, {"src": "/products/lb-cream-1.jpg", "thumb": "/products/lb-cream-1.jpg"}, {"src": "/products/lb-cream-2.jpg", "thumb": "/products/lb-cream-2.jpg"}, {"src": "/products/lb-red-1.jpg", "thumb": "/products/lb-red-1.jpg"}, {"src": "/products/lb-red-2.jpg", "thumb": "/products/lb-red-2.jpg"}, {"src": "/products/lb-pink-1.jpg", "thumb": "/products/lb-pink-1.jpg"}, {"src": "/products/lb-pink-2.jpg", "thumb": "/products/lb-pink-2.jpg"}, {"src": "/products/lb-info.jpg", "thumb": "/products/lb-info.jpg"}, {"src": "/products/lb-guide.jpg", "thumb": "/products/lb-guide.jpg"}, {"src": "/products/lb-sport.jpg", "thumb": "/products/lb-sport.jpg"}, {"src": "/products/lb-youth.jpg", "thumb": "/products/lb-youth.jpg"}, {"src": "/products/lb-pro.jpg", "thumb": "/products/lb-pro.jpg"}, {"src": "/products/lb-sole.jpg", "thumb": "/products/lb-sole.jpg"}, {"src": "/products/lb-convenient.jpg", "thumb": "/products/lb-convenient.jpg"}], "variations": [{"id": "cream-32", "label": "Cream, EU 32", "color": "cream", "size": "32", "price": 2560, "regularPrice": 3490, "stock": 5}, {"id": "cream-33", "label": "Cream, EU 33", "color": "cream", "size": "33", "price": 2560, "regularPrice": 3490, "stock": 5}, {"id": "cream-34", "label": "Cream, EU 34", "color": "cream", "size": "34", "price": 2560, "regularPrice": 3490, "stock